import { Text, View, Pressable, TextInput, StyleSheet } from 'react-native';
import { AntDesign } from '@expo/vector-icons';
import { Ionicons } from '@expo/vector-icons';
import { useNavigation } from '@react-navigation/native'
import EdiButton from '../EDICertificate/EdiButton';

export const EdiOrderDetailHeader = () => {
  return (
    <View style={styles.header}>

    <View style = {styles.leftSide} >
      <Text style = {{fontSize:20,color:'white'}}>edi:12345</Text>
      <Text  style = {{fontSize:20,color:'white'}}>order Number:55487859</Text>
    </View>

    <View  style = {styles.rightSide}>
      <AntDesign onPress={() => {
        navigation.navigate('Home')
      }} name="rightcircleo"
        size={35} color="white" />
       </View>
    </View>
  )
}



export const EdiHeader = ({ setModalOpen, setQuery, setFullData }) => {
  const navigation = useNavigation()
  return (
    <View style={styles.header}>

       <View style = {styles.leftSide} >
      <Ionicons onPress={() => {
        setModalOpen(true); setQuery(''); setFullData([])
      }}
        name="search-circle-sharp" size={48} color="white" />
    </View>

    <View  style = {styles.rightSide}>
      <AntDesign onPress={() => {
        navigation.navigate('Home')
      }} name="rightcircleo"
        size={40} color="white" />
       </View>
    </View>
  )
}



export const ModalHeader = ({ setModalOpen, isModalOpen, query, handleSearch }) => {
  return (
    <>
      <View style={styles.header}>
      
      <View style = {[styles.leftSide  ]}>
        <Pressable onPress={() => setModalOpen(!isModalOpen)}>
          <Text style={{ zIndex: 1000 }}>
            <AntDesign onPress={() => setModalOpen(!isModalOpen)}
              name="closecircle" size={35} color="white" />
          </Text>
        </Pressable>
        </View>

        <View style = {styles.rightSide}>
        <TextInput
          autoFocus={true}
          keyboardType='numeric'
          autoCapitalize="none"
          placeHolder='Search'
          autoCorrect={false}
          clearButtonMode="always"
          value={query}
          onChangeText={queryText => handleSearch(queryText)}
          style={styles.textInput}
        />
      </View>
      </View>
      {query && <View style={styles.notification}><Text style={styles.notificationText}>Edi Certificate</Text></View>}
    </>
  )
}

export const EdiTab = () => {
  
  return (
  
      <View style={styles.tabHeader}>
      <View style = {styles.TextInputTab}>
      <Ionicons onPress={() => {
        console.log('search')
      }}
        name="search-circle-sharp" size={48} color="blue" />
       </View>
      
          

    <Pressable style={({ pressed }) => [
        { backgroundColor: pressed ? '#d3d3d3' : 'blue'},
        styles.pressableDone
      ]} onPress={() => console.log('Done Pressed')}>
          <EdiButton  title = "Todo"/>
          <View style = {{ display:'flex',
    flexDirection:'row',
    alignItems: 'center',
    justifyContent: 'space-around',
    paddingVertical: 12,
    paddingHorizontal: 14,
    borderRadius: 10,
    elevation: 3,
    width:'50%',
    backgroundColor:'#d3d3d3',
    }}>
          <View style={styles.circle}>
         <Text style={styles.text}>25</Text>
        </View>
      <Text style={styles.textDone}>Done</Text>
          </View>
         
          </Pressable>
        
      
        </View>

    
  )
}



